<?php
/**
 * Prompt
 *
 * A prompt generated by the prompt builder tool and saved to the
 * history. Prompts belong to the user who saved them: the builder page
 * is public, the history is only visible to the signed-in owner. The
 * inputs column holds the complete form state as JSON so a saved
 * prompt can be loaded back into the form unchanged.
 *
 * @author Roan Buysse <roan@buysse.be>
 */

use Skeleton\Database\Database;

class Prompt {
	use \Skeleton\Object\Model;
	use \Skeleton\Object\Uuid;
	use \Skeleton\Object\Get;
	use \Skeleton\Object\Save;
	use \Skeleton\Object\Delete;

	/**
	 * Archive a prompt (soft delete)
	 *
	 * Archived prompts stay in the table but disappear from the
	 * history list.
	 *
	 * @access public
	 */
	public function archive(): void {
		$this->archived = date('Y-m-d H:i:s');
		$this->save();
	}

	/**
	 * Restore an archived prompt
	 *
	 * @access public
	 */
	public function restore(): void {
		$this->archived = null;
		$this->save();
	}

	/**
	 * Get the history of a user, newest first
	 *
	 * Returns the active (non-archived) prompts of one user, capped to
	 * the most recent ones so the page stays light.
	 *
	 * @access public
	 * @param int $user_id
	 * @param int $limit
	 * @return array<Prompt> $prompts
	 */
	public static function get_history(int $user_id, int $limit = 50): array {
		$database = Database::get();
		$rows = $database->get_all(
			'SELECT id FROM prompt WHERE user_id = ? AND archived IS NULL ORDER BY created DESC LIMIT ' . intval($limit),
			[ $user_id ]
		);

		$prompts = [];
		foreach ($rows as $row) {
			$prompts[] = self::get_by_id($row['id']);
		}

		return $prompts;
	}
}
